def car_race_collision(n: int):
    total_collisions = 0
    left_cars = list(range(1, n+1))
    right_cars = list(range(n+1, 2*n+1))

    for left_car in left_cars:
        for right_car in right_cars:
            if left_car == right_car:
                total_collisions += 1

    return total_collisions

